struct Fenwick {
    int n; vector<long long> bit;
    Fenwick(int n): n(n), bit(n + 1) {}
    void add(int i, long long v) {
        for (++i; i <= n; i += i & -i) bit[i] += v;
    }
    long long sumPrefix(int i) const {
        long long r = 0;
        for (; i > 0; i -= i & -i) r += bit[i];
        return r;
    }
    long long sum(int l, int r) const { return sumPrefix(r) - sumPrefix(l); }
};

void update(int p, int l, int r, int pos, long long val) {
    if (r - l == 1) { tree[p] = val; return; }
    int m = (l + r) / 2;
    if (pos < m) update(2*p, l, m, pos, val);
    else update(2*p+1, m, r, pos, val);
    tree[p] = tree[2*p] + tree[2*p+1];
}

