// Em cada nó, mantenha a reta atualmente melhor em algum ponto.
// Compare no meio e recursione onde a reta antiga pode vencer.

long long countInversions(vector<long long> values) {
    vector<long long> compressedValues = values;
    sort(compressedValues.begin(), compressedValues.end());
    compressedValues.erase(unique(compressedValues.begin(), compressedValues.end()), compressedValues.end());
    Fenwick frequencyTree(compressedValues.size());
    long long inversionCount = 0;
    for (int index = (int)values.size() - 1; index >= 0; --index) {
        int valueRank = lower_bound(compressedValues.begin(), compressedValues.end(), values[index]) - compressedValues.begin();
        inversionCount += frequencyTree.sum(0, valueRank);
        frequencyTree.add(valueRank, 1);
    }
    return inversionCount;
}
